script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { rg: 0 }; }
  renderVals() {
    const N = 10, L = ["7 Habits", "Get to know them", "Meeting summary", "About Vivint", "Product", "Pay", "Difficulty", "Your story", "Matt\u2019s Big 3", "Pullback"], cur = Math.max(0, Math.min(N - 1, this.state.rg || 0)), v = {};
    const go = (i) => (e) => { if (e && e.preventDefault) e.preventDefault(); this.setState({ rg: Math.max(0, Math.min(N - 1, i)) }); };
    for (let i = 0; i < N; i++) {
      v['rgGo' + i] = go(i);
      v['rgP' + i] = i === cur ? 'opacity: 1; transform: translate3d(0px, 0px, 0px)' : 'opacity: 0; transform: translate3d(0px, ' + (i < cur ? -16 : 16) + 'px, 0px); pointer-events: none; visibility: hidden';
      v['rgDot' + i] = i === cur ? 'background: #05E5AF; border: 2px solid #05E5AF; box-shadow: 0 0 0 6px rgba(5,229,175,0.18), 0 0 22px rgba(5,229,175,0.6)'
        : (i < cur ? 'background: #05E5AF; border: 2px solid #05E5AF' : 'background: #050807; border: 2px solid rgba(255,255,255,0.4)');
      v['rgLab' + i] = i === cur ? 'color: #ffffff; font-weight: 600' : 'color: rgba(255,255,255,' + (i < cur ? '0.75' : '0.5') + '); font-weight: 400';
    }
    v.rgFill = 'height: ' + (cur * 62) + 'px';
    v.rgPrev = go(cur - 1); v.rgNext = go(cur + 1);
    v.rgPrevS = cur === 0 ? 'opacity: 0; pointer-events: none' : 'opacity: 1';
    v.rgNextS = cur === N - 1 ? 'opacity: 0; pointer-events: none' : 'opacity: 1';
    v.rgNextT = cur < N - 1 ? 'Next: ' + L[cur + 1] : '';
    return v;
  }
}
